The graph of the line $x+y=b$ is a perpendicular bisector of the line segment from $(1,3)$ to $(5,7)$. What is the value of b?

Put your final answer within \boxed{}.

#include <iostream>
#include <cmath>
using namespace std;

int main() {
int x1 = 1, y1 = 3, x2 = 5, y2 = 7;
int b;

// Calculate the slope of the line segment
int slope = (y2 - y1) / (x2 - x1);

// Calculate the slope of the perpendicular bisector
int perpendicularSlope = -1 / slope;

// Calculate the y-intercept of the perpendicular bisector
int yIntercept = y1 - slope * x1;

// Calculate the value of b
b = perpendicularSlope * x1 + yIntercept;

cout << "The value of b is: " << b << endl;

return 0;
}

